/// Event streaming accessor
class PairEvents {
  const PairEvents(this._controller);

  final SmartContractController _controller;

  /// Create a unified WebSocket stream for multiple events.
  ///
  /// More efficient than individual streams - uses single WebSocket connection.
  ///
  /// Example:
  /// ```dart
  /// final stream = controller.events.websocketStream(
  ///   websocketUrl: 'wss://kepler-api.projectx.mx/mainnet/events',
  ///   headers: {'Api-Key': 'your-key'},
  /// );
  /// await stream.connect();
  ///
  /// // Listen to specific events
  /// stream.swap.listen((event) => print(event));
  ///
  /// // Or listen to all events
  /// stream.all.listen((event) { ... });
  /// ```
  multi_event_websocket_stream.MultiEventWebSocketStream websocketStream({
    required String websocketUrl,
    Map<String, String> headers = const {},
    bool autoReconnect = true,
    Duration reconnectDelay = const Duration(milliseconds: 300),
    Duration connectionTimeout = const Duration(seconds: 5),
    Duration pingInterval = const Duration(seconds: 10),
  }) {
    return multi_event_websocket_stream.MultiEventWebSocketStream(
      controller: _controller,
      websocketUrl: websocketUrl,
      headers: headers,
      autoReconnect: autoReconnect,
      reconnectDelay: reconnectDelay,
      connectionTimeout: connectionTimeout,
      pingInterval: pingInterval,
    );
  }

  /// Create a unified polling stream for multiple events.
  ///
  /// More efficient than individual streams - uses single API call.
  ///
  /// Example:
  /// ```dart
  /// final stream = controller.events.pollingStream(
  ///   pollingInterval: Duration(seconds: 10),
  /// );
  ///
  /// // Listen to specific events
  /// stream.swap.listen((event) => print(event));
  ///
  /// // Or listen to all events
  /// stream.all.listen((event) { ... });
  /// ```
  multi_event_polling_stream.MultiEventPollingStream pollingStream({
    Duration pollingInterval = const Duration(seconds: 10),
    String? startFrom,
  }) {
    return multi_event_polling_stream.MultiEventPollingStream(
      controller: _controller,
      pollingInterval: pollingInterval,
      startFrom: startFrom,
    );
  }

  swap_polling_stream.SwapPollingStream swapPolling() =>
      swap_polling_stream.SwapPollingStream(_controller);

  swap_websocket_stream.SwapWebSocketStream swapWebSocket({
    required String websocketUrl,
    Map<String, String> headers = const {},
    bool autoReconnect = true,
    Duration reconnectDelay = const Duration(seconds: 5),
    Duration connectionTimeout = const Duration(seconds: 15),
    Duration pingInterval = const Duration(seconds: 30),
  }) {
    return swap_websocket_stream.SwapWebSocketStream(
      controller: _controller,
      websocketUrl: websocketUrl,
      headers: headers,
      autoReconnect: autoReconnect,
      reconnectDelay: reconnectDelay,
      connectionTimeout: connectionTimeout,
      pingInterval: pingInterval,
    );
  }

  swap_no_fee_and_forward_polling_stream.SwapNoFeeAndForwardPollingStream
  swapNoFeeAndForwardPolling() =>
      swap_no_fee_and_forward_polling_stream.SwapNoFeeAndForwardPollingStream(
        _controller,
      );

  swap_no_fee_and_forward_websocket_stream.SwapNoFeeAndForwardWebSocketStream
  swapNoFeeAndForwardWebSocket({
    required String websocketUrl,
    Map<String, String> headers = const {},
    bool autoReconnect = true,
    Duration reconnectDelay = const Duration(seconds: 5),
    Duration connectionTimeout = const Duration(seconds: 15),
    Duration pingInterval = const Duration(seconds: 30),
  }) {
    return swap_no_fee_and_forward_websocket_stream.SwapNoFeeAndForwardWebSocketStream(
      controller: _controller,
      websocketUrl: websocketUrl,
      headers: headers,
      autoReconnect: autoReconnect,
      reconnectDelay: reconnectDelay,
      connectionTimeout: connectionTimeout,
      pingInterval: pingInterval,
    );
  }

  add_liquidity_polling_stream.AddLiquidityPollingStream
  addLiquidityPolling() =>
      add_liquidity_polling_stream.AddLiquidityPollingStream(_controller);

  add_liquidity_websocket_stream.AddLiquidityWebSocketStream
  addLiquidityWebSocket({
    required String websocketUrl,
    Map<String, String> headers = const {},
    bool autoReconnect = true,
    Duration reconnectDelay = const Duration(seconds: 5),
    Duration connectionTimeout = const Duration(seconds: 15),
    Duration pingInterval = const Duration(seconds: 30),
  }) {
    return add_liquidity_websocket_stream.AddLiquidityWebSocketStream(
      controller: _controller,
      websocketUrl: websocketUrl,
      headers: headers,
      autoReconnect: autoReconnect,
      reconnectDelay: reconnectDelay,
      connectionTimeout: connectionTimeout,
      pingInterval: pingInterval,
    );
  }

  remove_liquidity_polling_stream.RemoveLiquidityPollingStream
  removeLiquidityPolling() =>
      remove_liquidity_polling_stream.RemoveLiquidityPollingStream(_controller);

  remove_liquidity_websocket_stream.RemoveLiquidityWebSocketStream
  removeLiquidityWebSocket({
    required String websocketUrl,
    Map<String, String> headers = const {},
    bool autoReconnect = true,
    Duration reconnectDelay = const Duration(seconds: 5),
    Duration connectionTimeout = const Duration(seconds: 15),
    Duration pingInterval = const Duration(seconds: 30),
  }) {
    return remove_liquidity_websocket_stream.RemoveLiquidityWebSocketStream(
      controller: _controller,
      websocketUrl: websocketUrl,
      headers: headers,
      autoReconnect: autoReconnect,
      reconnectDelay: reconnectDelay,
      connectionTimeout: connectionTimeout,
      pingInterval: pingInterval,
    );
  }
}
